/*
 * SIMD-accelerated 3D Color LUT transform for 3-channel tables.
 * The table uses stride 4 (padded) for aligned 128-bit loads.
 *
 * For each pixel, trilinear interpolation is performed:
 *   1. Compute integer table indices and fractional shifts from R, G, B
 *   2. Load 8 table entries (cube corners) using stride-4 layout
 *   3. Interpolate along all three axes
 *   4. Clip and store result
 */

static void
ImagingColorLUT3D_linear_3ch_SIMD(
    Imaging imOut, Imaging imIn, INT16 *table,
    int size1D, int size2D, int size3D,
    int size1D_2D,
    UINT32 scale1D, UINT32 scale2D, UINT32 scale3D)
{
    int x, y;
    /* With stride 4, offsets between adjacent entries in each dimension */
    int stride1D = 4;                /* next entry in dim1: 4 INT16 */
    int stride2D = size1D * 4;       /* next entry in dim2: size1D * 4 INT16 */
    int stride3D = size1D_2D * 4;    /* next entry in dim3: size1D_2D * 4 INT16 */

#if defined(__AVX2__)
    {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize - 1; x += 2) {
                /* Process 2 pixels at once with AVX2 */
                __m256i indices, shifts;
                __m256i table_idx;
                __m256i ll, lr, rl, rr, left, right, result;
                __m256i inv_shift, sft;
                __m128i result_128;
                INT32 v0, v1;

                /* Load 2 pixels: R0,G0,B0,A0 and R1,G1,B1,A1 */
                /* Each pixel is 4 bytes (RGBA stored as UINT32) */
                UINT32 p0 = *(UINT32 *)&rowIn[x * 4];
                UINT32 p1 = *(UINT32 *)&rowIn[(x + 1) * 4];

                UINT8 r0 = p0 & 0xFF;
                UINT8 g0 = (p0 >> 8) & 0xFF;
                UINT8 b0 = (p0 >> 16) & 0xFF;
                UINT8 a0 = (p0 >> 24) & 0xFF;

                UINT8 r1 = p1 & 0xFF;
                UINT8 g1 = (p1 >> 8) & 0xFF;
                UINT8 b1 = (p1 >> 16) & 0xFF;
                UINT8 a1 = (p1 >> 24) & 0xFF;

                UINT32 idx1D_0 = r0 * scale1D;
                UINT32 idx2D_0 = g0 * scale2D;
                UINT32 idx3D_0 = b0 * scale3D;
                INT16 shift1D_0 = (SCALE_MASK & idx1D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_0 = (SCALE_MASK & idx2D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_0 = (SCALE_MASK & idx3D_0) >> (SCALE_BITS - SHIFT_BITS);
                int base0 = table_index3D(idx1D_0 >> SCALE_BITS,
                                           idx2D_0 >> SCALE_BITS,
                                           idx3D_0 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                UINT32 idx1D_1 = r1 * scale1D;
                UINT32 idx2D_1 = g1 * scale2D;
                UINT32 idx3D_1 = b1 * scale3D;
                INT16 shift1D_1 = (SCALE_MASK & idx1D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_1 = (SCALE_MASK & idx2D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_1 = (SCALE_MASK & idx3D_1) >> (SCALE_BITS - SHIFT_BITS);
                int base1 = table_index3D(idx1D_1 >> SCALE_BITS,
                                           idx2D_1 >> SCALE_BITS,
                                           idx3D_1 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                /* Process pixel 0 with SSE4.2 intrinsics */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_0;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_0;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_0;

                    /* Load 8 cube corners for pixel 0 */
                    __m128i t_ll0 = _mm_loadl_epi64((__m128i *)&table[base0]);                    /* [c0_0, c0_1, c0_2, 0] */
                    __m128i t_lr0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride1D]);          /* [c1_0, c1_1, c1_2, 0] */
                    __m128i t_rl0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride2D]);          /* [c2_0, c2_1, c2_2, 0] */
                    __m128i t_rr0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride2D + stride1D]);
                    __m128i t_ll3_0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D]);
                    __m128i t_lr3_0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride1D]);
                    __m128i t_rl3_0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D]);
                    __m128i t_rr3_0 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D + stride1D]);

                    /* Interpolate along dim1: leftleft = a*(1-shift) + b*shift */
                    __m128i mm_inv1D = _mm_set1_epi16(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi16(shift1D_0);
                    __m128i leftleft = _mm_add_epi16(
                        _mm_mullo_epi16(t_ll0, mm_inv1D),
                        _mm_mullo_epi16(t_lr0, mm_shift1D));
                    __m128i leftright = _mm_add_epi16(
                        _mm_mullo_epi16(t_rl0, mm_inv1D),
                        _mm_mullo_epi16(t_rr0, mm_shift1D));
                    __m128i rightleft = _mm_add_epi16(
                        _mm_mullo_epi16(t_ll3_0, mm_inv1D),
                        _mm_mullo_epi16(t_lr3_0, mm_shift1D));
                    __m128i rightright = _mm_add_epi16(
                        _mm_mullo_epi16(t_rl3_0, mm_inv1D),
                        _mm_mullo_epi16(t_rr3_0, mm_shift1D));

                    /* Interpolate along dim2: left = leftleft*(1-shift) + leftright*shift */
                    __m128i mm_inv2D = _mm_set1_epi16(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi16(shift2D_0);
                    __m128i left_p0 = _mm_add_epi16(
                        _mm_mullo_epi16(leftleft, mm_inv2D),
                        _mm_mullo_epi16(leftright, mm_shift2D));
                    __m128i right_p0 = _mm_add_epi16(
                        _mm_mullo_epi16(rightleft, mm_inv2D),
                        _mm_mullo_epi16(rightright, mm_shift2D));

                    /* Interpolate along dim3: result = left*(1-shift) + right*shift */
                    __m128i mm_inv3D = _mm_set1_epi16(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi16(shift3D_0);
                    __m128i result_p0 = _mm_add_epi16(
                        _mm_mullo_epi16(left_p0, mm_inv3D),
                        _mm_mullo_epi16(right_p0, mm_shift3D));

                    /* Shift right by SHIFT_BITS */
                    result_p0 = _mm_srai_epi16(result_p0, SHIFT_BITS);

                    /* Clip to 0..255 and pack */
                    /* Use packs_epi16 to clamp to [-128,127] then packus, but we need [0,255] */
                    /* First add PRECISION_ROUNDING and shift by PRECISION_BITS for clip8 */
                    /* Actually, after the SHIFT_BITS shift, values are in INT16 range.
                       We need to apply clip8 which adds PRECISION_ROUNDING and shifts by PRECISION_BITS.
                       But our result is already shifted by SHIFT_BITS, so the values should be
                       in the correct fixed-point representation for clip8. */
                    /* Simpler: since result is INT16 after >>SHIFT_BITS, use packus to get UINT8 */
                    /* But packus clamps to [0, 255] only for UINT16. We need to handle negatives. */
                    /* Use _mm_packus_epi16 which clamps INT16 to [0, 255] */
                    result_128 = _mm_packus_epi16(result_p0, result_p0);
                    v0 = _mm_cvtsi128_si32(result_128);
                    /* v0 has bytes [R, G, B, 0] in low 4 bytes, need to set alpha */
                    /* On little-endian: v0 = R | (G << 8) | (B << 16) | (0 << 24) */
                    v0 = (v0 & 0x00FFFFFF) | (a0 << 24);
                    rowOut[x] = v0;
                }

                /* Process pixel 1 with SSE4.2 intrinsics */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_1;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_1;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_1;

                    __m128i t_ll1 = _mm_loadl_epi64((__m128i *)&table[base1]);
                    __m128i t_lr1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride1D]);
                    __m128i t_rl1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride2D]);
                    __m128i t_rr1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride2D + stride1D]);
                    __m128i t_ll3_1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride3D]);
                    __m128i t_lr3_1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride1D]);
                    __m128i t_rl3_1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D]);
                    __m128i t_rr3_1 = _mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D + stride1D]);

                    __m128i mm_inv1D = _mm_set1_epi16(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi16(shift1D_1);
                    __m128i leftleft = _mm_add_epi16(
                        _mm_mullo_epi16(t_ll1, mm_inv1D),
                        _mm_mullo_epi16(t_lr1, mm_shift1D));
                    __m128i leftright = _mm_add_epi16(
                        _mm_mullo_epi16(t_rl1, mm_inv1D),
                        _mm_mullo_epi16(t_rr1, mm_shift1D));
                    __m128i rightleft = _mm_add_epi16(
                        _mm_mullo_epi16(t_ll3_1, mm_inv1D),
                        _mm_mullo_epi16(t_lr3_1, mm_shift1D));
                    __m128i rightright = _mm_add_epi16(
                        _mm_mullo_epi16(t_rl3_1, mm_inv1D),
                        _mm_mullo_epi16(t_rr3_1, mm_shift1D));

                    __m128i mm_inv2D = _mm_set1_epi16(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi16(shift2D_1);
                    __m128i left_p1 = _mm_add_epi16(
                        _mm_mullo_epi16(leftleft, mm_inv2D),
                        _mm_mullo_epi16(leftright, mm_shift2D));
                    __m128i right_p1 = _mm_add_epi16(
                        _mm_mullo_epi16(rightleft, mm_inv2D),
                        _mm_mullo_epi16(rightright, mm_shift2D));

                    __m128i mm_inv3D = _mm_set1_epi16(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi16(shift3D_1);
                    __m128i result_p1 = _mm_add_epi16(
                        _mm_mullo_epi16(left_p1, mm_inv3D),
                        _mm_mullo_epi16(right_p1, mm_shift3D));

                    result_p1 = _mm_srai_epi16(result_p1, SHIFT_BITS);
                    result_128 = _mm_packus_epi16(result_p1, result_p1);
                    v1 = _mm_cvtsi128_si32(result_128);
                    v1 = (v1 & 0x00FFFFFF) | (a1 << 24);
                    rowOut[x + 1] = v1;
                }
            }
            /* Handle remaining pixel if xsize is odd */
            for (; x < imOut->xsize; x++) {
                UINT8 *rowIn_x = (UINT8 *)imIn->image[y];
                char *rowOut_x = (char *)imOut->image[y];
                UINT32 index1D = rowIn_x[x * 4 + 0] * scale1D;
                UINT32 index2D = rowIn_x[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn_x[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_index3D(index1D >> SCALE_BITS,
                                        index2D >> SCALE_BITS,
                                        index3D >> SCALE_BITS,
                                        size1D, size1D_2D) * 4;

                INT16 inv1D = (1 << SHIFT_BITS) - shift1D;
                INT16 inv2D = (1 << SHIFT_BITS) - shift2D;
                INT16 inv3D = (1 << SHIFT_BITS) - shift3D;

                __m128i t_ll = _mm_loadl_epi64((__m128i *)&table[idx]);
                __m128i t_lr = _mm_loadl_epi64((__m128i *)&table[idx + stride1D]);
                __m128i t_rl = _mm_loadl_epi64((__m128i *)&table[idx + stride2D]);
                __m128i t_rr = _mm_loadl_epi64((__m128i *)&table[idx + stride2D + stride1D]);
                __m128i t_ll3 = _mm_loadl_epi64((__m128i *)&table[idx + stride3D]);
                __m128i t_lr3 = _mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride1D]);
                __m128i t_rl3 = _mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D]);
                __m128i t_rr3 = _mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D + stride1D]);

                __m128i mm_inv1D = _mm_set1_epi16(inv1D);
                __m128i mm_shift1D = _mm_set1_epi16(shift1D);
                __m128i leftleft = _mm_add_epi16(_mm_mullo_epi16(t_ll, mm_inv1D), _mm_mullo_epi16(t_lr, mm_shift1D));
                __m128i leftright = _mm_add_epi16(_mm_mullo_epi16(t_rl, mm_inv1D), _mm_mullo_epi16(t_rr, mm_shift1D));
                __m128i rightleft = _mm_add_epi16(_mm_mullo_epi16(t_ll3, mm_inv1D), _mm_mullo_epi16(t_lr3, mm_shift1D));
                __m128i rightright = _mm_add_epi16(_mm_mullo_epi16(t_rl3, mm_inv1D), _mm_mullo_epi16(t_rr3, mm_shift1D));

                __m128i mm_inv2D = _mm_set1_epi16(inv2D);
                __m128i mm_shift2D = _mm_set1_epi16(shift2D);
                __m128i left = _mm_add_epi16(_mm_mullo_epi16(leftleft, mm_inv2D), _mm_mullo_epi16(leftright, mm_shift2D));
                __m128i right = _mm_add_epi16(_mm_mullo_epi16(rightleft, mm_inv2D), _mm_mullo_epi16(rightright, mm_shift2D));

                __m128i mm_inv3D = _mm_set1_epi16(inv3D);
                __m128i mm_shift3D = _mm_set1_epi16(shift3D);
                __m128i result = _mm_add_epi16(_mm_mullo_epi16(left, mm_inv3D), _mm_mullo_epi16(right, mm_shift3D));

                result = _mm_srai_epi16(result, SHIFT_BITS);
                __m128i packed = _mm_packus_epi16(result, result);
                UINT32 v = _mm_cvtsi128_si32(packed);
                v = (v & 0x00FFFFFF) | (rowIn_x[x * 4 + 3] << 24);
                memcpy(rowOut_x + x * sizeof(v), &v, sizeof(v));
            }
        }
    }
#elif defined(__SSE4_2__)
    {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize; x++) {
                UINT32 p = *(UINT32 *)&rowIn[x * 4];
                UINT8 r = p & 0xFF;
