                    __m128i t_rl = _mm_loadl_epi64((__m128i *)&table[base0 + stride2D]);
                    __m128i t_rr = _mm_loadl_epi64((__m128i *)&table[base0 + stride2D + stride1D]);
                    __m128i t_ll3 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D]);
                    __m128i t_lr3 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride1D]);
                    __m128i t_rl3 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D]);
                    __m128i t_rr3 = _mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D + stride1D]);

