/*
 * SIMD-accelerated 3D Color LUT transform for 3-channel tables.
 * The table uses stride 4 (padded) for aligned 128-bit loads.
 *
 * The interpolation uses 16-bit fixed-point arithmetic with SHIFT_BITS (15)
 * for the interpolation weights. Since table values can be up to 16320
 * (255 << PRECISION_BITS), and the weight up to 32768 (1 << SHIFT_BITS),
 * the intermediate products overflow INT16. We therefore expand to 32-bit
 * for the multiply-add, then shift and narrow.
 *
 * Processing strategy:
 *   SSE4.2: Process 1 pixel at a time, using 4-wide INT32 vectors
 *   AVX2:   Process 2 pixels at a time, using 8-wide INT32 vectors
 */

static void
ImagingColorLUT3D_linear_3ch_SIMD(
    Imaging imOut, Imaging imIn, INT16 *table,
    int size1D, int size2D, int size3D,
    int size1D_2D,
    UINT32 scale1D, UINT32 scale2D, UINT32 scale3D)
{
    int x, y;
    /* With stride 4, offsets between adjacent entries in each dimension */
    int stride1D = 4;
    int stride2D = size1D * 4;
    int stride3D = size1D_2D * 4;

#if defined(__AVX2__)
    {
        __m128i mm_precision_rounding = _mm_set1_epi32(PRECISION_ROUNDING);

        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize - 1; x += 2) {
                UINT32 p0 = *(UINT32 *)&rowIn[x * 4];
                UINT32 p1 = *(UINT32 *)&rowIn[(x + 1) * 4];

                UINT8 r0 = p0 & 0xFF, g0 = (p0 >> 8) & 0xFF, b0 = (p0 >> 16) & 0xFF, a0 = (p0 >> 24) & 0xFF;
                UINT8 r1 = p1 & 0xFF, g1 = (p1 >> 8) & 0xFF, b1 = (p1 >> 16) & 0xFF, a1 = (p1 >> 24) & 0xFF;

                UINT32 idx1D_0 = r0 * scale1D, idx2D_0 = g0 * scale2D, idx3D_0 = b0 * scale3D;
                INT16 shift1D_0 = (SCALE_MASK & idx1D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_0 = (SCALE_MASK & idx2D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_0 = (SCALE_MASK & idx3D_0) >> (SCALE_BITS - SHIFT_BITS);
                int base0 = table_index3D(idx1D_0 >> SCALE_BITS,
                                           idx2D_0 >> SCALE_BITS,
                                           idx3D_0 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                UINT32 idx1D_1 = r1 * scale1D, idx2D_1 = g1 * scale2D, idx3D_1 = b1 * scale3D;
                INT16 shift1D_1 = (SCALE_MASK & idx1D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_1 = (SCALE_MASK & idx2D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_1 = (SCALE_MASK & idx3D_1) >> (SCALE_BITS - SHIFT_BITS);
                int base1 = table_index3D(idx1D_1 >> SCALE_BITS,
                                           idx2D_1 >> SCALE_BITS,
                                           idx3D_1 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                /* Interpolate for pixel 0 using INT32 arithmetic */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_0;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_0;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_0;

                    __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0]));
                    __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride1D]));
                    __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride2D]));
                    __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride2D + stride1D]));
                    __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D]));
                    __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride1D]));
                    __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D]));
                    __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D + stride1D]));

                    /* Interpolate along dim1 */
                    __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi32(shift1D_0);
                    __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                    __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                    __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                    __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                    /* Interpolate along dim2 */
                    __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi32(shift2D_0);
                    __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                    __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                    /* Interpolate along dim3 */
                    __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi32(shift3D_0);
                    __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                    /* Clip: add rounding and shift by PRECISION_BITS */
                    result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                    /* Pack INT32 to UINT8: packs -> packus */
                    __m128i packed = _mm_packus_epi16(_mm_packs_epi32(result, result), _mm_packs_epi32(result, result));
                    /* Wait, packs_epi32 clamps to [-32768, 32767], but we need [0, 255].
                       After the PRECISION_BITS shift, values should be in 0..255 range.
                       packs_epi32 will produce INT16 values, then packus_epi16 will clamp to [0,255].
                       Actually we can just use packus directly:
                       _mm_packus_epi32 is available in SSE4.1! It packs INT32 to UINT8 with [0,255] clamping.
                       But it's actually AVX-only for the 128-bit version... let me check.
                       Actually _mm_packus_epi32 IS available in SSE4.1 (SSE4.2 includes SSE4.1).
                       It packs 4 INT32 values to 4 UINT16 values with [0, 65535] clamping.
                       Then we need another step to go from UINT16 to UINT8.
                    */
                    /* Use packs_epi32 then packus_epi16:
                       - packs_epi32: INT32 -> INT16, clamps to [-32768, 32767]
                       - Since our values are in [0, 255] after PRECISION_BITS shift, this is safe
                       - packus_epi16: INT16 -> UINT8, clamps to [0, 255] */
                    __m128i i16 = _mm_packs_epi32(result, result);
                    __m128i u8 = _mm_packus_epi16(i16, i16);
                    UINT32 v = _mm_cvtsi128_si32(u8);
                    v = (v & 0x00FFFFFF) | (a0 << 24);
                    rowOut[x] = v;
                }

                /* Interpolate for pixel 1 */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_1;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_1;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_1;

                    __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1]));
                    __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride1D]));
                    __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride2D]));
                    __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride2D + stride1D]));
                    __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D]));
                    __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride1D]));
                    __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D]));
                    __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D + stride1D]));

                    __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi32(shift1D_1);
                    __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                    __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                    __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                    __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                    __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi32(shift2D_1);
                    __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                    __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                    __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi32(shift3D_1);
                    __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                    result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                    __m128i i16 = _mm_packs_epi32(result, result);
                    __m128i u8 = _mm_packus_epi16(i16, i16);
                    UINT32 v = _mm_cvtsi128_si32(u8);
                    v = (v & 0x00FFFFFF) | (a1 << 24);
                    rowOut[x + 1] = v;
                }
            }
            /* Handle remaining pixel */
            for (; x < imOut->xsize; x++) {
                UINT32 p = *(UINT32 *)&rowIn[x * 4];
                UINT8 r = p & 0xFF, g = (p >> 8) & 0xFF, b = (p >> 16) & 0xFF, a = (p >> 24) & 0xFF;

                UINT32 index1D = r * scale1D, index2D = g * scale2D, index3D = b * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_index3D(index1D >> SCALE_BITS, index2D >> SCALE_BITS,
                                        index3D >> SCALE_BITS, size1D, size1D_2D) * 4;
                INT16 inv1D = (1 << SHIFT_BITS) - shift1D;
                INT16 inv2D = (1 << SHIFT_BITS) - shift2D;
                INT16 inv3D = (1 << SHIFT_BITS) - shift3D;

                __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx]));
                __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride1D]));
                __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D]));
                __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D + stride1D]));
                __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D]));
                __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride1D]));
                __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D]));
                __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D + stride1D]));

                __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                __m128i mm_shift1D = _mm_set1_epi32(shift1D);
                __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                __m128i mm_shift2D = _mm_set1_epi32(shift2D);
                __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                __m128i mm_shift3D = _mm_set1_epi32(shift3D);
                __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                __m128i i16 = _mm_packs_epi32(result, result);
                __m128i u8 = _mm_packus_epi16(i16, i16);
                UINT32 v = _mm_cvtsi128_si32(u8);
                v = (v & 0x00FFFFFF) | (a << 24);
                rowOut[x] = v;
            }
        }
    }
#elif defined(__SSE4_2__)
    {
        __m128i mm_precision_rounding = _mm_set1_epi32(PRECISION_ROUNDING);

        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize; x++) {
                UINT32 p = *(UINT32 *)&rowIn[x * 4];
                UINT8 r = p & 0xFF, g = (p >> 8) & 0xFF, b = (p >> 16) & 0xFF, a = (p >> 24) & 0xFF;

                UINT32 index1D = r * scale1D, index2D = g * scale2D, index3D = b * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_index3D(index1D >> SCALE_BITS, index2D >> SCALE_BITS,
                                        index3D >> SCALE_BITS, size1D, size1D_2D) * 4;
                INT16 inv1D = (1 << SHIFT_BITS) - shift1D;
                INT16 inv2D = (1 << SHIFT_BITS) - shift2D;
                INT16 inv3D = (1 << SHIFT_BITS) - shift3D;

                /* Load 8 cube corners as INT32 (4 channels per entry, stride 4) */
                __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx]));
                __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride1D]));
                __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D]));
                __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D + stride1D]));
                __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D]));
                __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride1D]));
                __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D]));
                __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D + stride1D]));

                /* Interpolate along dim1 */
                __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                __m128i mm_shift1D = _mm_set1_epi32(shift1D);
                __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                /* Interpolate along dim2 */
                __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                __m128i mm_shift2D = _mm_set1_epi32(shift2D);
                __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                /* Interpolate along dim3 */
                __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                __m128i mm_shift3D = _mm_set1_epi32(shift3D);
                __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                /* Clip: add rounding and shift by PRECISION_BITS */
                result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                /* Pack INT32 to UINT8 */
                __m128i i16 = _mm_packs_epi32(result, result);
                __m128i u8 = _mm_packus_epi16(i16, i16);
                UINT32 v = _mm_cvtsi128_si32(u8);
                v = (v & 0x00FFFFFF) | (a << 24);
                rowOut[x] = v;
            }
        }
    }
#endif
}

/*
 * SIMD-accelerated 3D Color LUT transform for 3-channel tables.
 * The table uses stride 4 (padded) for aligned 128-bit loads.
 *
 * The interpolation uses 16-bit fixed-point arithmetic with SHIFT_BITS (15)
 * for the interpolation weights. Since table values can be up to 16320
 * (255 << PRECISION_BITS), and the weight up to 32768 (1 << SHIFT_BITS),
 * the intermediate products overflow INT16. We therefore expand to 32-bit
 * for the multiply-add, then shift and narrow.
 *
 * Processing strategy:
 *   SSE4.2: Process 1 pixel at a time, using 4-wide INT32 vectors
 *   AVX2:   Process 2 pixels at a time, using 8-wide INT32 vectors
 */

static void
ImagingColorLUT3D_linear_3ch_SIMD(
    Imaging imOut, Imaging imIn, INT16 *table,
    int size1D, int size2D, int size3D,
    int size1D_2D,
    UINT32 scale1D, UINT32 scale2D, UINT32 scale3D)
{
    int x, y;
    /* With stride 4, offsets between adjacent entries in each dimension */
    int stride1D = 4;
    int stride2D = size1D * 4;
    int stride3D = size1D_2D * 4;

#if defined(__AVX2__)
    {
        __m128i mm_precision_rounding = _mm_set1_epi32(PRECISION_ROUNDING);

        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize - 1; x += 2) {
                UINT32 p0 = *(UINT32 *)&rowIn[x * 4];
                UINT32 p1 = *(UINT32 *)&rowIn[(x + 1) * 4];

                UINT8 r0 = p0 & 0xFF, g0 = (p0 >> 8) & 0xFF, b0 = (p0 >> 16) & 0xFF, a0 = (p0 >> 24) & 0xFF;
                UINT8 r1 = p1 & 0xFF, g1 = (p1 >> 8) & 0xFF, b1 = (p1 >> 16) & 0xFF, a1 = (p1 >> 24) & 0xFF;

                UINT32 idx1D_0 = r0 * scale1D, idx2D_0 = g0 * scale2D, idx3D_0 = b0 * scale3D;
                INT16 shift1D_0 = (SCALE_MASK & idx1D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_0 = (SCALE_MASK & idx2D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_0 = (SCALE_MASK & idx3D_0) >> (SCALE_BITS - SHIFT_BITS);
                int base0 = table_index3D(idx1D_0 >> SCALE_BITS,
                                           idx2D_0 >> SCALE_BITS,
                                           idx3D_0 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                UINT32 idx1D_1 = r1 * scale1D, idx2D_1 = g1 * scale2D, idx3D_1 = b1 * scale3D;
                INT16 shift1D_1 = (SCALE_MASK & idx1D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_1 = (SCALE_MASK & idx2D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_1 = (SCALE_MASK & idx3D_1) >> (SCALE_BITS - SHIFT_BITS);
                int base1 = table_index3D(idx1D_1 >> SCALE_BITS,
                                           idx2D_1 >> SCALE_BITS,
                                           idx3D_1 >> SCALE_BITS,
                                           size1D, size1D_2D) * 4;

                /* Interpolate for pixel 0 using INT32 arithmetic */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_0;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_0;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_0;

                    __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0]));
                    __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride1D]));
                    __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride2D]));
                    __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride2D + stride1D]));
                    __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D]));
                    __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride1D]));
                    __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D]));
                    __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base0 + stride3D + stride2D + stride1D]));

                    /* Interpolate along dim1 */
                    __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi32(shift1D_0);
                    __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                    __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                    __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                    __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                    /* Interpolate along dim2 */
                    __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi32(shift2D_0);
                    __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                    __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                    /* Interpolate along dim3 */
                    __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi32(shift3D_0);
                    __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                    /* Clip: add rounding and shift by PRECISION_BITS */
                    result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                    /* Pack INT32 to UINT8: packs -> packus */
                    __m128i packed = _mm_packus_epi16(_mm_packs_epi32(result, result), _mm_packs_epi32(result, result));
                    /* Wait, packs_epi32 clamps to [-32768, 32767], but we need [0, 255].
                       After the PRECISION_BITS shift, values should be in 0..255 range.
                       packs_epi32 will produce INT16 values, then packus_epi16 will clamp to [0,255].
                       Actually we can just use packus directly:
                       _mm_packus_epi32 is available in SSE4.1! It packs INT32 to UINT8 with [0,255] clamping.
                       But it's actually AVX-only for the 128-bit version... let me check.
                       Actually _mm_packus_epi32 IS available in SSE4.1 (SSE4.2 includes SSE4.1).
                       It packs 4 INT32 values to 4 UINT16 values with [0, 65535] clamping.
                       Then we need another step to go from UINT16 to UINT8.
                    */
                    /* Use packs_epi32 then packus_epi16:
                       - packs_epi32: INT32 -> INT16, clamps to [-32768, 32767]
                       - Since our values are in [0, 255] after PRECISION_BITS shift, this is safe
                       - packus_epi16: INT16 -> UINT8, clamps to [0, 255] */
                    __m128i i16 = _mm_packs_epi32(result, result);
                    __m128i u8 = _mm_packus_epi16(i16, i16);
                    UINT32 v = _mm_cvtsi128_si32(u8);
                    v = (v & 0x00FFFFFF) | (a0 << 24);
                    rowOut[x] = v;
                }

                /* Interpolate for pixel 1 */
                {
                    INT16 inv1D = (1 << SHIFT_BITS) - shift1D_1;
                    INT16 inv2D = (1 << SHIFT_BITS) - shift2D_1;
                    INT16 inv3D = (1 << SHIFT_BITS) - shift3D_1;

                    __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1]));
                    __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride1D]));
                    __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride2D]));
                    __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride2D + stride1D]));
                    __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D]));
                    __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride1D]));
                    __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D]));
                    __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[base1 + stride3D + stride2D + stride1D]));

                    __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                    __m128i mm_shift1D = _mm_set1_epi32(shift1D_1);
                    __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                    __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                    __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                    __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                    __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                    __m128i mm_shift2D = _mm_set1_epi32(shift2D_1);
                    __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                    __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                    __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                    __m128i mm_shift3D = _mm_set1_epi32(shift3D_1);
                    __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                    result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                    __m128i i16 = _mm_packs_epi32(result, result);
                    __m128i u8 = _mm_packus_epi16(i16, i16);
                    UINT32 v = _mm_cvtsi128_si32(u8);
                    v = (v & 0x00FFFFFF) | (a1 << 24);
                    rowOut[x + 1] = v;
                }
            }
            /* Handle remaining pixel */
            for (; x < imOut->xsize; x++) {
                UINT32 p = *(UINT32 *)&rowIn[x * 4];
                UINT8 r = p & 0xFF, g = (p >> 8) & 0xFF, b = (p >> 16) & 0xFF, a = (p >> 24) & 0xFF;

                UINT32 index1D = r * scale1D, index2D = g * scale2D, index3D = b * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_index3D(index1D >> SCALE_BITS, index2D >> SCALE_BITS,
                                        index3D >> SCALE_BITS, size1D, size1D_2D) * 4;
                INT16 inv1D = (1 << SHIFT_BITS) - shift1D;
                INT16 inv2D = (1 << SHIFT_BITS) - shift2D;
                INT16 inv3D = (1 << SHIFT_BITS) - shift3D;

                __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx]));
                __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride1D]));
                __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D]));
                __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D + stride1D]));
                __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D]));
                __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride1D]));
                __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D]));
                __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D + stride1D]));

                __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                __m128i mm_shift1D = _mm_set1_epi32(shift1D);
                __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                __m128i mm_shift2D = _mm_set1_epi32(shift2D);
                __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                __m128i mm_shift3D = _mm_set1_epi32(shift3D);
                __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                __m128i i16 = _mm_packs_epi32(result, result);
                __m128i u8 = _mm_packus_epi16(i16, i16);
                UINT32 v = _mm_cvtsi128_si32(u8);
                v = (v & 0x00FFFFFF) | (a << 24);
                rowOut[x] = v;
            }
        }
    }
#elif defined(__SSE4_2__)
    {
        __m128i mm_precision_rounding = _mm_set1_epi32(PRECISION_ROUNDING);

        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            INT32 *rowOut = (INT32 *)imOut->image32[y];
            for (x = 0; x < imOut->xsize; x++) {
                UINT32 p = *(UINT32 *)&rowIn[x * 4];
                UINT8 r = p & 0xFF, g = (p >> 8) & 0xFF, b = (p >> 16) & 0xFF, a = (p >> 24) & 0xFF;

                UINT32 index1D = r * scale1D, index2D = g * scale2D, index3D = b * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_index3D(index1D >> SCALE_BITS, index2D >> SCALE_BITS,
                                        index3D >> SCALE_BITS, size1D, size1D_2D) * 4;
                INT16 inv1D = (1 << SHIFT_BITS) - shift1D;
                INT16 inv2D = (1 << SHIFT_BITS) - shift2D;
                INT16 inv3D = (1 << SHIFT_BITS) - shift3D;

                /* Load 8 cube corners as INT32 (4 channels per entry, stride 4) */
                __m128i t_ll = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx]));
                __m128i t_lr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride1D]));
                __m128i t_rl = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D]));
                __m128i t_rr = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride2D + stride1D]));
                __m128i t_ll3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D]));
                __m128i t_lr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride1D]));
                __m128i t_rl3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D]));
                __m128i t_rr3 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i *)&table[idx + stride3D + stride2D + stride1D]));

                /* Interpolate along dim1 */
                __m128i mm_inv1D = _mm_set1_epi32(inv1D);
                __m128i mm_shift1D = _mm_set1_epi32(shift1D);
                __m128i leftleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll, mm_inv1D), _mm_mullo_epi32(t_lr, mm_shift1D)), SHIFT_BITS);
                __m128i leftright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl, mm_inv1D), _mm_mullo_epi32(t_rr, mm_shift1D)), SHIFT_BITS);
                __m128i rightleft = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_ll3, mm_inv1D), _mm_mullo_epi32(t_lr3, mm_shift1D)), SHIFT_BITS);
                __m128i rightright = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(t_rl3, mm_inv1D), _mm_mullo_epi32(t_rr3, mm_shift1D)), SHIFT_BITS);

                /* Interpolate along dim2 */
                __m128i mm_inv2D = _mm_set1_epi32(inv2D);
                __m128i mm_shift2D = _mm_set1_epi32(shift2D);
                __m128i left = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(leftleft, mm_inv2D), _mm_mullo_epi32(leftright, mm_shift2D)), SHIFT_BITS);
                __m128i right = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(rightleft, mm_inv2D), _mm_mullo_epi32(rightright, mm_shift2D)), SHIFT_BITS);

                /* Interpolate along dim3 */
                __m128i mm_inv3D = _mm_set1_epi32(inv3D);
                __m128i mm_shift3D = _mm_set1_epi32(shift3D);
                __m128i result = _mm_srai_epi32(_mm_add_epi32(_mm_mullo_epi32(left, mm_inv3D), _mm_mullo_epi32(right, mm_shift3D)), SHIFT_BITS);

                /* Clip: add rounding and shift by PRECISION_BITS */
                result = _mm_srai_epi32(_mm_add_epi32(result, mm_precision_rounding), PRECISION_BITS);

                /* Pack INT32 to UINT8 */
                __m128i i16 = _mm_packs_epi32(result, result);
                __m128i u8 = _mm_packus_epi16(i16, i16);
                UINT32 v = _mm_cvtsi128_si32(u8);
                v = (v & 0x00FFFFFF) | (a << 24);
                rowOut[x] = v;
            }
        }
    }
#endif
}

